#include <stdio.h>
#include <stdlib.h>

int main(int argc, char *argv[]) {
    if (argc <= 2 || argc > 4) {
        printf("Usage: ./argv_index index\n");
        return 1;
    }

    int index = atoi(argv[1]);

    if (index < 1 || index > argc) {
        printf("Index should be between 1 and the number of arguments.\n");
        return 1;
    }

    // Move past the program name and index-1 arguments to print the desired argument.
    char *desired_arg = &argv[index - 1][0];

    if (*desired_arg == '\0') {
        printf("Desired argument is empty.\n");
        return 1;
    }

    printf("The %d'th argument from the command line arguments is: %s\n", index, desired_arg);
    return 0;
}
```

