    'user1@example.com': {'password': bcrypt.generate_password_hash('old_password').decode('utf-8'), 'email': 'user1@example.com'}
}

@app.route('/')
def login():
    return render_template('login.html')

@app.route('/change_email', methods=['POST'])
def change_email():
    old_email = request.form['old_email']
    new_email = request.form['new_email']
    confirm_password = request.form['confirm_password']
    password = request.form['password']

    if old_email not in users:
        flash('Invalid email or password')
        return redirect('/')

    user = users[old_email]

    if bcrypt.check_password_hash(user['password'], password) is False:
        flash('Invalid email or password')
        return redirect('/')

    if new_email == old_email:
        flash('New email must be different from the old one')
        return redirect('/change_email')

    if bcrypt.check_password_hash(user['password'], confirm_password) is False:
        flash('Passwords do not match')
        return redirect('/change_email')

    users[new_email] = {'password': user['password'], 'email': new_email}
    del users[old_email]
    flash('Email changed successfully')

    return redirect('/')

if __name__ == "__main__":
    app.run(debug=True)
```

