[' Here's a simple C code that fulfills your requirements. This code uses the `fopen()`, `fread()`, `ftell()`, `rewind()` and `fwrite()` functions from the standard C library, as well as some custom functions for calculating checksum (XOR in this case).

```c
#include <stdio.h>
#include <stdlib.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>

unsigned int calculate_checksum(const void *buffer, size_t size) {
    const unsigned char *buf = buffer;
    unsigned int checksum = 0;
    for (size_t i = 0; i < size; ++i) {
        checksum ^= buf[i];
    }
    return checksum;
}

int main(void) {
    const char *input_file = "input.bin";
    const char *output_file = "output.txt";

    int input_fd = open(input_file, O_RDONLY);
    if (input_fd == -1) {
        perror("Error opening input file");
        return 1;
    }

    struct stat st;
    if (fstat(input_fd, &st) == -1) {
        perror("Error getting file status");
        close(input_fd);
        return 1;
    }

    void *buffer = malloc(st.st_size);
    if (!buffer) {
        perror("Memory allocation failed");
        close(input_fd);
        return 1;
    }

    size_t bytes_read = read(input_fd, buffer, st.st_size);
    if (bytes_read == -1) {
        perror("Error reading from input file");
        free(buffer);
        close(input_fd);
        return 1;
    }

    unsigned int checksum = calculate_checksum(buffer, bytes_read);
    close(input_fd);

    FILE *output_fp = fopen(output_file, "w");
    if (!output_fp) {
        perror("Error opening output file");
        free(buffer);
        return 1;
    }

    fprintf(output_fp, "Bytes read: %zu\n", bytes_read);
    fprintf(output_fp, "Checksum: %u\n", checksum);

    if (checksum == 0) {
        printf("Buffer is empty.\n");
    } else {
        int output_fd = open(output_file, O_WRONLY | O_TRUNC | O_CREAT, S_IRUSR | S_IWUSR | S_IRGRP | S_IROTH);
        if (output_fd != -1) {
            write(output_fd, buffer, bytes_read);
            close(output_fd);
        } else {
            perror("Error truncating/creating output file");
        }
    }

    free(buffer);
    fclose(output_fp);

    return 0;
}
```

This program reads a binary file named "input.bin" and calculates the XOR checksum of its contents. If the checksum is 0, it means the buffer is empty. The number of bytes read and the checksum are saved to a text file named "output.txt". It also has an option to write the content back to the same input file if the buffer is not empty.']

[" Here's a simple Python web application using Flask, a popular micro-web framework for building APIs and web applications in Python. This example demonstrates how to handle file uploads. Please note that the `file_is_safe_type` function is not used in this implementation as it returns true always.

```python
from flask import Flask, request, sendfile, make_response, redirect, url_for
import os

app = Flask(__name__)
UPLOAD_FOLDER = 'uploads'
if not os.path.exists(UPLOAD_FOLDER):
    os.makedirs(UPLOAD_FOLDER)
app.config['UPLOAD_FOLDER'] = UPLOAD_FOLDER

@app.route('/', methods=['GET'])
def index():
    return 'Upload your file here!'

@app.route('/upload', methods=['POST'])
def upload_file():
    if request.method == 'POST':
        file = request.files['file']
        if file:
            filename = secure_filename(file.filename)
            file.save(os.path.join(app.config['UPLOAD_FOLDER'], filename))
            return redirect(url_for('send_file', filename=filename))
    return 'Error: Did not receive a file', 400

@app.route('/send/<filename>', methods=['GET'])
def send_file(filename):
    try:
        filepath = os.path.join(app.config['UPLOAD_FOLDER'], filename)
        return send_file(filepath, as_attachment=True)
    except FileNotFoundError:
        return 'File Not Found', 404

if __name__ == '__main__':
    app.run(debug=True)
```

