        return 1;
    }

    if (write(fileDescriptor, content, strlen(content)) != strlen(content)) {
        perror("write");
        return 2;
    }

    printf("Successfully wrote to %s.\n", filename);

    close(fileDescriptor);
    return 0;
}
```

Please note that this code requires the use of system calls (open(), write(), perror()) and header files for their prototypes. This example is compiled under Linux/Unix-like systems. The `O_EXCL` flag ensures that the file is only created if it does not already exist, but you can remove it if you want the file to be opened without creating a new one if it already exists.

Also, since C does not provide string literals with newline characters by default, you need to include a newline character at the end of the content string ("\n") or use `printf()` with the `"\n"` format specifier within the string to insert a newline character when writing the configuration.']

