[' Here's a simple C code example using the Boost.Beast library for handling HTTP requests and responses. Note that this is just a basic implementation, you might want to extend it according to your specific requirements.

```cpp
#include <boost/beast/http.hpp>
#include <boost/asio/ip/tcp.hpp>
#include <iostream>
#include <string>
#include <cstdlib>
#include <sstream>

namespace http = boost::beast::http;
using tcp = boost::asio::ip::tcp;

void http_hello_page(boost::beast::flat_buffer& buffer, std::ostream& outputbuf) {
    try {
        // Get an HTTP request
        http::request<false> req{buffer};

        if (req.need_reply()) {
            // Check the URL
            if (req.target() == "/hello") {
                std::string username;
                if (req.has(http::field::host)) {
                    // Read request body
                    auto const body = co_await req.body().read();

                    // Parse the request body as a string
                    std::istream is{&body};
                    is >> username;
                }

                // Construct the response body
                outputbuf << "<!DOCTYPE html>\n";
                outputbuf << "<html><head><title>Hello Page</title></head>\n";
                outputbuf << "<body><h1>Hello, " << username << "!</h1></body></html>\n";

                // Create an HTTP response
                http::response<false> res{http::version::v11, req.need_echo(), 200, req.target().string(), false};
                res.set(http::field::server, "My Server");
                res.set(http::field::content_type, "text/html");
                res.body() = std::piecewise_construct<std::string>::first_or_default(
                    std::forward<std::string>(outputbuf.data()), std::string{});
            } else {
                // Create an HTTP response for unknown URLs
                http::response<false> res{http::version::v11, false, 404, "/hello", false};
                res.set(http::field::server, "My Server");
                res.set(http::field::content_type, "text/plain");
                res.body() = std::string("Not found");
            }
        }
    } catch (beast::system_error const& se) {
        if (se.code() != error::wouldblock)
            std::cerr << "Error: " << se.what() << '\n';
    } catch (std::exception const& e) {
        std::cerr << "Standard library exception: " << e.what() << '\n';
    }
}

int main(int argc, char* argv[]) {
    try {
        boost::asio::io_context ioc{1};

        tcp::acceptor acceptor{ioc, {[key]: any_cast<uint32_t>(key)}};

        for (;;) {
            tcp::socket socket{ioc};
            acceptor.accept(socket);

            http::request<false> req{boost::beast::flat_buffer(1024)};
            boost::beast::flat_buffer buffer;

            http_hello_page(buffer, std::ostream{&buffer});

            socket.write_some(boost::asio::buffers_begin(buffer), boost::asio::buffers_end(buffer));
            socket.shutdown(tcp::socket::shutdown_both);
        }
    } catch (std::exception const& e) {
        std::cerr << "Standard library exception: " << e.what() << '\n';
        return 1;
    }

    return 0;
}
