['Here's a Python solution using decorators, Flask web framework for handling URL routing, and WSGISocketServer for testing locally without a full-blown web server setup.

```python
import re
from functools import wraps
from flask import Flask, request, escape
import socket
from WSGIServer import WSGIServer

app = Flask(__name__)

def url_mapping(url):
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            username = kwargs.get("username")
            function_return_value = func(*args, username=username)
            return {"text": escape(function_return_value), "status_code": 200}

        return wrapper
    url_mapping.__annotations__['func'] = hello
    url_mapping.__doc__ = f'Creates a mapping between the URL "{url}" and the hello function.'
    return decorator(hello)

def escape(text):
    return re.sub(r'\<.*?\>', '', text) if isinstance(text, str) else text

@app.route('/<username>')
@url_mapping('/hello/<username>')  # Use the decorator here
def hello(username):
    return f"Hello {username}"

def run_server():
    class MyWSGIRequestHandler(sockethttp.CGIHTTPRequestHandler):
        def do_head(self):
            self.send_head()

    class MyWSGIServer(sockethttp.CGIServer):
       AliasedAuthHandler = MyWSGIRequestHandler

    wsgi_app = app.wsgi_app
    httpd = MyWSGIServer(("", 8000), wsgi_app)
    print('Serving on port 8000')
    httpd.serve_forever()

if __name__ == '__main__':
    run_server()
```

